starter.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        for (int i = 0; i < n; i++) {
            int p = in.nextInt();
            if (p < 1024) {
                System.out.println("well-known");
            } else if (p < 49151) {
                System.out.println("registered");
            } else {
                System.out.println("ephemeral");
            }
        }
    }
}

